const { readFileSync, writeFileSync } = require('node:fs');
const { join } = require('node:path');
const root = join(__dirname, '..');
const destination = join(root, 'contracts/service-mcp-gateway/src');
const contract = readFileSync(join(root, 'mcp-tools.json'), 'utf8').trim();
const spec = JSON.parse(readFileSync(join(root, 'openapi.json'), 'utf8'));
writeFileSync(
  join(destination, 'mcp-tools.ts'),
  '// Generated from catalog.schemas.ts; do not edit.\nexport const mcpCatalogContract = ' +
    contract +
    ' as const;\n'
);
// OpenAPI's existing types generator preserves opaque JSON as unknown, not any.
const names = Object.keys(spec.components.schemas);
writeFileSync(
  join(destination, 'index.ts'),
  [
    '// Generated by scripts/export-mcp-contracts.cjs; do not edit.',
    "import type { components } from './service-mcp-gateway.types.js';",
    ...names.map(
      (name) => `export type ${name} = components['schemas']['${name}'];`
    ),
    "export { mcpCatalogContract } from './mcp-tools.js';",
    '',
  ].join('\n')
);
